'use strict';
const HOME_ETFS=['SPY','VOO','DIA','IWM','TLT','GLD'];
const HOME_TECH_ETFS=['QQQ','VGT','XLK','SOXX'];
const HOME_SECTORS=[{name:'Market',symbols:['VOO','SPY','QQQ','IWM']},{name:'Tech',symbols:['VGT','XLK','AAPL','MSFT']},{name:'Semiconductors',symbols:['SOXX','NVDA','AMD','INTC']},{name:'Energy',symbols:['XLE','BE','CEG','VST']}];
const HOME_SECTOR_SYMBOLS=[...new Set(HOME_SECTORS.flatMap(g=>g.symbols))];
const HOME_STOCKS=['NVDA','AAPL','MSFT','AMZN','GOOG','TSLA','BE','INTC'];
const HOME_NAMES={SPY:'S&P 500',VOO:'Vanguard S&P 500',QQQ:'Nasdaq 100',VGT:'Vanguard technology',XLK:'S&P technology sector',SOXX:'Semiconductors',DIA:'Dow Jones',IWM:'Russell 2000',TLT:'Long-term Treasuries',GLD:'Gold',NVDA:'NVIDIA',AAPL:'Apple',MSFT:'Microsoft',AMZN:'Amazon',GOOG:'Alphabet',TSLA:'Tesla',BE:'Bloom Energy',INTC:'Intel',AMD:'AMD',XLE:'Energy sector ETF',CEG:'Constellation Energy',VST:'Vistra'};
let homeBusy=false;
function homeTrackPriority(person){const r=typeof politicianRating==='function'?politicianRating(person):null;return r&&r.score!==null&&!r.stale&&r.score>=55?r.score:0}
function latestPurchases(rows=signalData,now=Date.now()){
 const today=new Date(now).toISOString().slice(0,10),cutoff=new Date(now-90*86400000).toISOString().slice(0,10),counts=new Map(),seen=new Set();
 return rows.filter(r=>r.type==='Purchase'&&r.quality!=='User-provided'&&disclosedDate(r)>=cutoff&&disclosedDate(r)<=today&&r.traded<=today)
 .sort((a,b)=>homeTrackPriority(b.person)-homeTrackPriority(a.person)||disclosedDate(b).localeCompare(disclosedDate(a))||b.traded.localeCompare(a.traded))
 .filter(r=>{const key=[r.person,r.ticker,r.traded,disclosedDate(r),r.asset,r.owner].join('|');if(seen.has(key)||(counts.get(r.person)||0)>=2)return false;seen.add(key);counts.set(r.person,(counts.get(r.person)||0)+1);return true}).slice(0,6);
}
function strongInvestorMoves(rows=signalData,now=Date.now()){
 const today=new Date(now).toISOString().slice(0,10),cutoff=new Date(now-90*86400000).toISOString().slice(0,10),counts=new Map(),seen=new Set();
 return rows.filter(r=>['Purchase','Sale'].includes(r.type)&&r.quality!=='User-provided'&&homeTrackPriority(r.person)>0&&disclosedDate(r)>=cutoff&&disclosedDate(r)<=today&&r.traded<=today).sort((a,b)=>disclosedDate(b).localeCompare(disclosedDate(a))||homeTrackPriority(b.person)-homeTrackPriority(a.person)).filter(r=>{const k=[r.person,r.ticker,r.type,r.traded,r.asset,r.owner].join('|');if(seen.has(k)||(counts.get(r.person)||0)>=2)return false;seen.add(k);counts.set(r.person,(counts.get(r.person)||0)+1);return true}).slice(0,6);
}
function miniChart(p,symbol){const points=chartPoints(p,'1M');if(points.length<2)return '<span class="mini-empty">History unavailable</span>';const values=points.map(p=>p[1]),lo=Math.min(...values),hi=Math.max(...values),path=values.map((v,i)=>`${i?'L':'M'}${(i/(values.length-1)*160).toFixed(1)},${(37-(v-lo)/Math.max(.01,hi-lo)*32).toFixed(1)}`).join(' ');return `<svg viewBox="0 0 160 42" role="img" aria-label="${esc(symbol)} one month closing prices"><path d="${path}" fill="none" stroke="${values.at(-1)>=values[0]?'#16805a':'#bd4141'}" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`}
function quoteCard(symbol){const p=displayQuote(symbol),delta=p?.previousClose?(p.latest/p.previousClose-1)*100:null,saved=workspaceState.symbols.includes(symbol);return `<article class="quote-card" aria-busy="${!p}"><div class="quote-card-top"><button class="quote-link" data-ticker="${symbol}"><b>${symbol}</b><small>${esc(HOME_NAMES[symbol]||p?.name||symbol)}</small></button><button class="bookmark-stock ${saved?'saved':''}" data-bookmark="${symbol}" aria-label="${saved?'Remove':'Bookmark'} ${symbol}" aria-pressed="${saved}" ${!workspaceReady||workspaceBusy?'disabled':''}>${saved?'★':'☆'}</button></div><button class="quote-chart" data-ticker="${symbol}" aria-label="Open ${symbol} chart"><div><strong>${p?money(p.latest,p.currency):'—'}</strong><span class="${delta===null?'muted':delta>=0?'gain':'loss'}">${delta===null?'—':signed(delta)} <small>day</small></span></div>${miniChart(PRICES[symbol],symbol)}</button><small class="quote-date">${quoteLabel(p)} · 1M chart</small></article>`}
function renderAccount(){const user=workspaceState.user;$('#accountControls').innerHTML=user?`<span class="account-email" title="${esc(user.email)}">${esc(user.email)}</span><a href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out</a>`:'<a class="account-signin" href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in with ChatGPT</a>';$('#bookmarkStatus').textContent=user?'Saved to your ChatGPT account':'Guest bookmarks · this browser. Sign in to sync across devices.';}
function followerReturn(r,prices=PRICES){
 const d=disclosedDate(r),p=prices[r.ticker?.trim().toUpperCase()];
 if(r.type!=='Purchase'||!['Stock','ADR','ETF','Call options','Partnership units'].includes(r.asset)||!d||!p||p.error||!(p.latest>0))return null;
 const dates=Object.keys(p.closes||{}).filter(k=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&k>d&&k<=p.asOf&&p.closes[k]>0).sort(),entry=dates[0];
 if(!entry)return null;
 return {pct:(p.latest/p.closes[entry]-1)*100,then:p.closes[entry],basisDate:entry,asOf:p.asOf,stale:!!p.stale,underlying:r.asset==='Call options'};
}
function followerCell(r){const p=followerReturn(r);return `<td class="home-disclosure-return ${p?(p.pct>=0?'gain':'loss'):'muted'}" title="${p?esc('Entry close '+date(p.basisDate)+'; latest close '+date(p.asOf)):'No completed closing price after disclosure available'}">${p?percent(p):'—'}<small>${p?'From '+date(p.basisDate)+(p.underlying?' · stock only':'')+(p.stale?' · stale':''):'Awaiting price / date'}</small></td>`}
function renderHome(){if(typeof renderPurchasesRibbon==='function')renderPurchasesRibbon();if(typeof renderFavoritesRibbon==='function')renderFavoritesRibbon();renderSharedBuying();if(typeof renderHomeInsights==='function')renderHomeInsights();
 if(!$('#homeView'))return;if(typeof renderContext==='function')renderContext();
 $('#homePurchases').innerHTML=strongInvestorMoves().map(r=>`<tr><td><button class="home-person" data-profile="${esc(r.person)}">${esc(r.person)}</button>${politicianRole(r.person)}<small>${esc(r.owner)}</small></td><td><button class="home-ticker" data-ticker="${esc(r.ticker)}">${esc(r.ticker)}</button><small>${esc(r.asset)}</small></td><td>${date(r.traded)}</td><td>${disclosedDate(r)?date(disclosedDate(r)):'Unknown'}</td><td>${esc(r.amount)}</td>${followerCell(r.type==='Sale'?{...r,type:'Purchase'}:r)}<td><span class="type-badge ${r.type.toLowerCase()}">${esc(r.type)}</span>${r.type==='Sale'?'<small>Stock move after sale</small>':''}</td><td><button class="row-details" data-detail="${esc(r.id)}" aria-label="Details for ${esc(r.person)} ${esc(r.ticker)} purchase">↗</button></td></tr>`).join('')||'<tr><td colspan="8">No recent moves from politicians with a usable Positive or Strong score. Browse all disclosures for unassessed activity.</td></tr>';
 if($('#homeSectorGrid'))$('#homeSectorGrid').innerHTML=HOME_SECTORS.map(g=>`<section class="sector-square" aria-label="${esc(g.name)} instruments"><h2>${esc(g.name)}</h2><div class="sector-quadrants">${g.symbols.map(quoteCard).join('')}</div></section>`).join('');$('#homeETFs').innerHTML=HOME_ETFS.map(quoteCard).join('');if($('#homeTechETFs'))$('#homeTechETFs').innerHTML=HOME_TECH_ETFS.map(quoteCard).join('');$('#homeStocks').innerHTML=HOME_STOCKS.map(quoteCard).join('');
 $('#homeBookmarks').innerHTML=workspaceState.symbols.map(s=>`<span class="favorite-chip"><button data-ticker="${esc(s)}">${esc(s)} <b>${displayQuote(s)?money(displayQuote(s).latest,displayQuote(s).currency):'—'}</b></button><button data-bookmark="${esc(s)}" aria-label="Remove ${esc(s)} bookmark" ${workspaceBusy?'disabled':''}>×</button></span>`).join('')||'<span class="muted">Tap a star to bookmark a stock.</span>';renderAccount();
}
async function refreshHome(){if(homeBusy)return;homeBusy=true;renderHome();try{for(const symbols of [HOME_SECTOR_SYMBOLS,workspaceState.symbols,HOME_ETFS,HOME_TECH_ETFS,HOME_STOCKS,...(typeof CONTEXT_ASSETS!=='undefined'?[CONTEXT_ASSETS.map(a=>a[0])]:[])]){await loadMarketPrices(symbols);renderHome()}}finally{homeBusy=false}}
if(typeof window!=='undefined'){
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-bookmark]');if(!b||workspaceBusy||!workspaceReady)return;const symbol=b.dataset.bookmark;await workspaceAction({kind:'watch',symbol,enabled:!workspaceState.symbols.includes(symbol)});renderHome()});
 $('#homeTickerSearch').onsubmit=e=>{e.preventDefault();openStock($('#homeTickerInput').value)};
 renderHome();refreshHome();setInterval(()=>{if(!document.hidden)refreshHome()},15*60000);
}
